const b=$input.first().json.body||{};
const L=['en','ar','hi','zh','ur','es'].includes(b.lang)?b.lang:'en';
const T={
  en: `Your request has been sent. A person from the support team will contact you.`,
  ar: `تم إرسال طلبك. سيتواصل معك أحد أفراد فريق الدعم.`,
  hi: `आपका अनुरोध भेज दिया गया है। सहायता टीम का कोई व्यक्ति आपसे संपर्क करेगा।`,
  zh: `你的请求已发送。支持团队的工作人员会联系你。`,
  ur: `آپ کی درخواست بھیج دی گئی ہے۔ سپورٹ ٹیم کا کوئی فرد آپ سے رابطہ کرے گا۔`,
  es: `Tu solicitud ha sido enviada. Una persona del equipo de apoyo te contactará.`
};
const D={"en": "Guidance, not regulated financial advice.", "ar": "إرشاد وليس نصيحة مالية منظمة.", "hi": "मार्गदर्शन, विनियमित वित्तीय सलाह नहीं।", "zh": "仅为指导，非受监管的财务建议。", "ur": "رہنمائی، منظم مالی مشورہ نہیں۔", "es": "Orientación, no asesoramiento financiero regulado."};
const staff=`Support request (user consented to share). Gap: £${b.gap}. Preferred language: ${b.lang||'en'}. Summary: ${b.summary}`;
return [{json:{message:T[L]+' '+D[L],staffMessage:staff,lang:L}}];
